#include <iostream>
#include <unordered_map>
#include <vector>

int subarraySum(const std::vector<int>& nums, int k) {
    std::unordered_map<int, int> prefixCounts;
    prefixCounts[0] = 1;
    int total = 0;
    int count = 0;
    for (int num : nums) {
        total += num;
        auto it = prefixCounts.find(total - k);
        if (it != prefixCounts.end()) {
            count += it->second;
        }
        prefixCounts[total]++;
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    int k;
    std::cin >> k;
    std::cout << subarraySum(nums, k) << "\n";
    return 0;
}

